param([int]$TimeoutSeconds=30)
$ErrorActionPreference='Stop';$port=5673
if(Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue){throw 'Port 5673 is occupied; refusing to affect the existing listener.'}
$tempRoot=Join-Path $env:TEMP ('g5-tunnel-reconnect-'+[Guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Path $tempRoot;$runner=$null
try{$script=Join-Path $PSScriptRoot 'Start-G5RabbitMqTunnel.ps1';$argsLine='-NoLogo -NoProfile -File "'+$script+'"';$runner=Start-Process -FilePath (Join-Path $PSHOME 'pwsh.exe') -ArgumentList $argsLine -PassThru -WindowStyle Hidden -RedirectStandardOutput (Join-Path $tempRoot 'stdout.log') -RedirectStandardError (Join-Path $tempRoot 'stderr.log')
  $deadline=(Get-Date).AddSeconds($TimeoutSeconds);$listener=$null;while((Get-Date)-lt$deadline-and-not$listener){if($runner.HasExited){throw 'Tunnel runner exited before connecting.'};$listener=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue|Select-Object -First 1;Start-Sleep -Milliseconds 300};if(-not$listener){throw 'Timed out waiting for the initial tunnel.'}
  $oldPid=[int]$listener.OwningProcess;$owner=Get-Process -Id $oldPid;if($owner.ProcessName-ne'ssh'){throw 'Tunnel listener belongs to an unexpected process.'};Stop-Process -Id $oldPid -Force
  $deadline=(Get-Date).AddSeconds(10);do{$listener=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue|Select-Object -First 1;if(-not$listener){break};Start-Sleep -Milliseconds 250}while((Get-Date)-lt$deadline);if($listener){throw 'Tunnel listener stayed open after SSH child termination.'}
  $deadline=(Get-Date).AddSeconds($TimeoutSeconds);$new=$null;while((Get-Date)-lt$deadline-and-not$new){if($runner.HasExited){throw 'Tunnel runner exited after interruption.'};$candidate=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue|Select-Object -First 1;if($candidate-and$candidate.OwningProcess-ne$oldPid){$new=$candidate};Start-Sleep -Milliseconds 300};if(-not$new){throw 'Tunnel did not reconnect before timeout.'};& (Join-Path $PSScriptRoot 'Test-G5RabbitMqTunnel.ps1');Write-Output "PASS: SSH tunnel reconnected after interruption (PID $oldPid -> $($new.OwningProcess))."
}finally{if($runner-and-not$runner.HasExited){Stop-Process -Id $runner.Id -Force -ErrorAction SilentlyContinue};$listener=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue|Select-Object -First 1;if($listener){$p=Get-Process -Id $listener.OwningProcess -ErrorAction SilentlyContinue;if($p-and$p.ProcessName-eq'ssh'){Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue}};Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue}
